import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
P=ROOT/'app/src/main/assets/expert_diag_v2.json'
d=json.load(open(P,encoding='utf-8')); by={i['id']:i for i in d['items']}

def gate(i,check,confirm,evidence='field_isolation_inference'):
    it=by[i]; marker='[원인별 분리시험] '
    if not any(marker in x for x in it['field_sequence']): it['field_sequence'].append(marker+check)
    if confirm not in it['confirm_if']: it['confirm_if'].append(confirm)
    it['specificity_gate']={'status':'CAUSE_SPECIFIC_PRE_TEARDOWN','check':check,'confirm':confirm,'evidence':evidence,'note':'서로 다른 원인을 분해 전에 가르기 위한 현장 분리시험. OEM 수치가 없는 경우 정상측 비교/격리만 사용.'}
    it.pop('diagnostic_limit',None)

def shared(ids,boundary,limit,post,evidence='field_isolation_boundary'):
    for i in ids:
        it=by[i]
        it['specificity_gate']={'status':'SHARED_ASSEMBLY_BOUNDARY','assembly_boundary':boundary,'evidence':evidence,'note':'현장 시험으로 해당 어셈블리까지는 확정할 수 있으나, 이 내부 세부원인은 분해 전 억지로 단정하지 않는다.'}
        it['diagnostic_limit']={'pre_teardown_result':boundary,'limit':limit,'post_teardown_checks':post}

